Y_OFFSET = 0.7
X_OFFSET = 0.0

class Font(dict):
    def __getitem__(self, key):
    # Intercepts lookups; if the value is a dict, returns Width.
        val = super().__getitem__(key)
        if isinstance(val, Glyph):
            return val["Width"]
        return val

    def get(self, key, default=None):
    # Ensures .get() shares the exact same transformation logic as bracket lookups.
        try:
            return self[key]
        except KeyError:
            return default

    def get_glyph(self, key, default=None):
        try:
            val = super().__getitem__(key)
        except:
            return default
        return val

class Glyph(dict):
    width_offset = 0.0
    def __getitem__(self, key):
        val = super().__getitem__(key)
        if isinstance(val, (float, int)):
            r = val
            if "Width" in key:
                r += self.width_offset
            return r
        return val

    def get(self, key, default=None):
    # Ensures .get() shares the exact same transformation logic as bracket lookups.
        try:
            return self[key]
        except KeyError:
            return default

    def get_raw(self, key, default=None):
        try:
            val = super().__getitem__(key)
        except KeyError:
            return default
        return val

class SplineSet(list):
    width_offset = 0.0

    def __getitem__(self, index):
    #Intercepts lookups and slicing to transform coordinates on read.
        val = super().__getitem__(index)
        if isinstance(index, slice):
            return [self._transform_item(item) for item in val]
        return self._transform_item(val)

    def __iter__(self):
    #Ensures loops and unpacking yield transformed coordinates.
        for item in super().__iter__():
            yield self._transform_item(item)

    def _transform_item(self, item):
    #Transforms a single spline command tuple, e.g., ('M', (x, y)).
        if isinstance(item, tuple) and len(item) == 2 and isinstance(item[0], str):
            op, coords = item
            transformed_coords = self._transform_coords(coords)
            return (op, transformed_coords)
        return item

    def _transform_coords(self, coords):
    #Recursively scales coordinates and shifts X coordinates (even indices).
        if isinstance(coords, tuple):
            res = []
            for i, val in enumerate(coords):
                if isinstance(val, (int, float)):
                    scaled = val
                    # Add width_offset * 0.5 ONLY to X coordinates (even indices: 0, 2, 4...)
                    if i % 2 == 0:
                        scaled += (self.width_offset * 0.5)
                    res.append(scaled)
                else:
                    res.append(val)
            return tuple(res)
        return coords

